void bk7258_yuv_buf_init(void)
{
  uint32_t reg;

  /* Power on the video pipeline and enable YUV_BUF's (and H264's,
   * required alongside it even for direct-capture mode) clock gate
   * before touching this module's own registers.
   */

  reg = getreg32(BK7258_SYS_REG_0X10);
  reg &= ~BK7258_SYS_PWD_VIDP;
  putreg32(reg, BK7258_SYS_REG_0X10);

  reg = getreg32(BK7258_SYS_REG_0X0D);
  reg |= BK7258_SYS_H264_CKEN | BK7258_SYS_YUV_CKEN;
  putreg32(reg, BK7258_SYS_REG_0X0D);

  printf("bk7258_yuv_buf: init: power/clock enabled, reg0x10=0x%08x "
         "reg0x0d=0x%08x\n",
         (unsigned int)getreg32(BK7258_SYS_REG_0X10),
         (unsigned int)getreg32(BK7258_SYS_REG_0X0D));

  /* Global control: soft_reset is active-low (0 = held in reset,
   * 1 = reset released / module active) -- confirmed against the
   * reference implementation's yuv_buf_ll_global_soft_reset_enable()/
   * _disable() naming (enable() writes 0, disable() writes 1) and
   * yuv_buf_ll_init()'s pulse (0, then 1, ending at 1).  This must end
   * with soft_reset=1: leaving it at 0 holds the entire module's
   * sampling/edge-detect state machine in reset, which independently
   * explains "every register field is configured correctly yet
   * int_status never sets a single bit" -- the module never leaves
   * its reset state to begin with, so no downstream register (ctrl,
   * int_en) can have any effect regardless of its value.
   * clk_gate_bypass is set per yuv_buf_ll_init() as well.
   */

  putreg32(0, YUV_BUF_GLOBAL_CTRL);
  printf("bk7258_yuv_buf: init: global_ctrl after write(0)=0x%08x\n",
         (unsigned int)getreg32(YUV_BUF_GLOBAL_CTRL));

  putreg32(YUV_BUF_GLOBAL_CTRL_SOFT_RESET, YUV_BUF_GLOBAL_CTRL);
  printf("bk7258_yuv_buf: init: global_ctrl after write(soft_reset=1)="
         "0x%08x\n", (unsigned int)getreg32(YUV_BUF_GLOBAL_CTRL));

  putreg32(YUV_BUF_GLOBAL_CTRL_SOFT_RESET | YUV_BUF_GLOBAL_CTRL_CLK_GATE_BYPASS,
           YUV_BUF_GLOBAL_CTRL);
  printf("bk7258_yuv_buf: init: global_ctrl after write(soft_reset=1,"
         "clk_gate_bypass=1)=0x%08x (readback %s)\n",
         (unsigned int)getreg32(YUV_BUF_GLOBAL_CTRL),
         (getreg32(YUV_BUF_GLOBAL_CTRL) ==
          (YUV_BUF_GLOBAL_CTRL_SOFT_RESET | YUV_BUF_GLOBAL_CTRL_CLK_GATE_BYPASS))
         ? "MATCHES expected value" : "DOES NOT MATCH expected value!");

  irq_attach(BK7258_IRQ_YUVB, bk7258_yuv_buf_isr, NULL);
  up_enable_irq(BK7258_IRQ_YUVB);

  printf("bk7258_yuv_buf: init: complete, irq=%d attached and enabled\n",
         (int)BK7258_IRQ_YUVB);
}

